def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common non-separator color is the tile background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    row_cuts = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    col_cuts = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def blocks(size, cuts):
        result = []
        start = 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = blocks(h, row_cuts)
    col_blocks = blocks(w, col_cuts)

    output = []
    for r0, r1 in row_blocks:
        out_row = []
        for c0, c1 in col_blocks:
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if marks >= 2 else background)
        output.append(out_row)
    return output
